{
  "$schema": "https://raw.githubusercontent.com/tauri-apps/tauri/dev/crates/tauri-cli/schema.json",
  "productName": "Devboule",
  "version": "0.1.0",
  "identifier": "com.devboule.app",
  "build": {
    "frontendDist": "../dist",
    "devUrl": "http://localhost:1420",
    "beforeDevCommand": "npm run dev",
    "beforeBuildCommand": "bash -c 'if [ \"${DEVBOULE_BUNDLE_ORACLE_EMBEDDER:-}\" = 1 ]; then bash scripts/stage-oracle-embedder.sh --full; else bash scripts/stage-oracle-embedder.sh --lite; fi' && bash scripts/stage-devboule-mcp.sh && npm run build"
  },
  "app": {
    "windows": [
      {
        "title": "Devboule",
        "width": 1400,
        "height": 900,
        "minWidth": 1024,
        "minHeight": 768,
        "center": true,
        "decorations": true,
        "resizable": true
      }
    ],
    "security": {
      "csp": {
        "default-src": "'self'",
        "script-src": "'self'",
        "style-src": "'self' 'unsafe-inline'",
        "font-src": "'self'",
        "img-src": "'self' data:",
        "connect-src": "'self' ipc: http://ipc.localhost",
        "frame-src": "'self' artifact: http://artifact.localhost"
      }
    }
  },
  "bundle": {
    "active": true,
    "targets": "all",
    "icon": [
      "icons/32x32.png",
      "icons/128x128.png",
      "icons/128x128@2x.png",
      "icons/icon.icns",
      "icons/icon.ico"
    ],
    "resources": [
      "../oracle",
      "resources/censor/semgrep-rules.yml",
      "resources/oracle-models",
      "../pi-sidecar/*"
    ],
    "externalBin": ["binaries/devboule-mcp"]
  }
}

